use clap::{Arg, ArgAction, Command};
use clap_complete::{generate, Shell};
use std::io;

fn cli() -> Command {
    Command::new("melody_cli")
        .version("0.20.0")
        .about("A CLI wrapping the Melody language compiler")
        .arg(
            Arg::new("input")
                .value_name("INPUT_FILE_PATH")
                .help("Read from a file\nUse '-' and or pipe input to read from stdin"),
        )
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("OUTPUT_FILE_PATH")
                .help("Write to a file"),
        )
        .arg(
            Arg::new("no-color")
                .short('n')
                .long("no-color")
                .action(ArgAction::SetTrue)
                .help("Print output with no color"),
        )
        .arg(
            Arg::new("repl")
                .short('r')
                .long("repl")
                .action(ArgAction::SetTrue)
                .help("Start the Melody REPL"),
        )
        .arg(
            Arg::new("completions")
                .long("generate-completions")
                .conflicts_with_all(["output", "repl"])
                .help("Outputs completions for the selected shell\nTo use, write the output to the appropriate location for your shell"),
        )
        .arg(
            Arg::new("test")
                .short('t')
                .long("test")
                .conflicts_with_all(["completions", "repl", "output"])
                .help("Test the compiled regex against a string"),
        )
        .arg(
            Arg::new("test-file")
                .short('f')
                .long("test-file")
                .conflicts_with_all(["completions", "repl", "output", "test"])
                .help("Test the compiled regex against the contents of a file"),
        )
}

fn main() {
    let matches = cli().get_matches();
    if let Some(shell) = matches.get_one::<String>("completions") {
        let sh: Option<Shell> = shell.parse().ok();
        match sh {
            Some(sh) => {
                let mut cmd = cli();
                generate(sh, &mut cmd, "melody", &mut io::stdout());
            }
            None => {
                println!("Unknown or unsupported shell: '{}'\nTry one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'\n", shell);
            }
        }
        return;
    }
    println!("ok");
}
