//! Compiles Melody source code into an ECMAScript regular expression.

use pest::iterators::Pair;
use pest::Parser;
use std::collections::HashMap;

#[derive(pest_derive::Parser)]
#[grammar = "grammar.pest"]
struct MelodyParser;

/// Converts line comments (`// ...`) placed at the start of a line into block
/// comments, which is the only comment form understood by the grammar. Line
/// endings are normalised to `\n` in the process.
fn preprocess(source: &str) -> String {
    source
        .lines()
        .map(|line| match line.trim_start().strip_prefix("//") {
            Some(rest) => format!("/*{}*/", rest),
            None => line.to_string(),
        })
        .collect::<Vec<_>>()
        .join("\n")
}

type Variables = HashMap<String, String>;

/// Compiles the given Melody source into a regular expression string.
pub fn compile(source: &str) -> Result<String, String> {
    let source = preprocess(source);
    let mut pairs = MelodyParser::parse(Rule::root, &source).map_err(|e| e.to_string())?;
    let root = pairs.next().expect("root rule always present");

    let mut variables = Variables::new();
    let mut output = String::new();

    for statement in root.into_inner() {
        if statement.as_rule() == Rule::EOI {
            continue;
        }
        output.push_str(&compile_statement(statement, &mut variables)?);
    }

    Ok(output)
}

fn compile_statement(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    match pair.as_rule() {
        Rule::literal => Ok(compile_literal(pair.as_str())),
        Rule::raw => Ok(compile_raw(pair.as_str())),
        Rule::range => compile_range(pair),
        Rule::symbol => compile_symbol(pair),
        Rule::negative_class => compile_negative_class(pair),
        Rule::variable_invocation => compile_variable_invocation(pair, variables),
        Rule::variable_declaration => compile_variable_declaration(pair, variables),
        Rule::quantifier => compile_quantifier(pair, variables),
        Rule::group_declaration => compile_group(pair, variables),
        Rule::assertion_declaration => compile_assertion(pair, variables),
        other => Err(format!("unexpected rule {:?}", other)),
    }
}

fn compile_block(pair: Pair<Rule>, variables: &mut Variables) -> Result<Vec<String>, String> {
    pair.into_inner()
        .map(|statement| compile_statement(statement, variables))
        .collect()
}

const SPECIAL_CHARACTERS: &[char] = &[
    '$', '(', ')', '*', '+', '.', '?', '[', ']', '^', '{', '|', '}',
];

fn escape_special(text: &str) -> String {
    let mut output = String::with_capacity(text.len());
    for character in text.chars() {
        if SPECIAL_CHARACTERS.contains(&character) {
            output.push('\\');
        }
        output.push(character);
    }
    output
}

fn compile_literal(text: &str) -> String {
    let quote = text.chars().next().unwrap_or('"');
    let content = &text[1..text.len() - 1];

    // Only the escaped quote is unescaped; all other escape sequences are
    // valid in regular expressions and are kept as they are.
    let mut unescaped = String::with_capacity(content.len());
    let mut characters = content.chars();
    while let Some(character) = characters.next() {
        if character == '\\' {
            match characters.next() {
                Some(next) if next == quote => unescaped.push(quote),
                Some(next) => {
                    unescaped.push('\\');
                    unescaped.push(next);
                }
                None => unescaped.push('\\'),
            }
        } else {
            unescaped.push(character);
        }
    }

    escape_special(&unescaped)
}

fn compile_raw(text: &str) -> String {
    let content = &text[1..text.len() - 1];
    content.replace("\\`", "`")
}

fn compile_range(pair: Pair<Rule>) -> Result<String, String> {
    let mut negative = false;
    let mut bounds: Vec<char> = Vec::new();

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::not => negative = true,
            _ => bounds.push(inner.as_str().chars().next().unwrap_or_default()),
        }
    }

    let start = bounds.first().copied().unwrap_or_default();
    let end = bounds.get(1).copied().unwrap_or_default();

    Ok(if negative {
        format!("[^{}-{}]", start, end)
    } else {
        format!("[{}-{}]", start, end)
    })
}

fn compile_symbol(pair: Pair<Rule>) -> Result<String, String> {
    let mut negative = false;
    let mut name = "";

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::not => negative = true,
            Rule::symbol_identifier => name = inner.as_str(),
            _ => {}
        }
    }

    symbol_to_regex(name, negative).map(str::to_string)
}

fn symbol_to_regex(name: &str, negative: bool) -> Result<&'static str, String> {
    let output = match (name, negative) {
        ("char", false) => ".",
        ("char", true) => return Err("negative char not allowed".to_string()),
        ("space", false) => " ",
        ("space", true) => "[^ ]",
        ("whitespace", false) => "\\s",
        ("whitespace", true) => "\\S",
        ("digit", false) => "\\d",
        ("digit", true) => "\\D",
        ("word", false) => "\\w",
        ("word", true) => "\\W",
        ("newline", false) => "\\n",
        ("newline", true) => "[^\\n]",
        ("tab", false) => "\\t",
        ("tab", true) => "[^\\t]",
        ("return", false) => "\\r",
        ("return", true) => "[^\\r]",
        ("feed", false) => "\\f",
        ("feed", true) => "[^\\f]",
        ("null", false) => "\\0",
        ("null", true) => "[^\\0]",
        ("vertical", false) => "\\v",
        ("vertical", true) => "[^\\v]",
        ("alphabetic", false) => "[a-zA-Z]",
        ("alphabetic", true) => "[^a-zA-Z]",
        ("alphanumeric", false) => "[a-zA-Z0-9]",
        ("alphanumeric", true) => "[^a-zA-Z0-9]",
        ("boundary", false) => "\\b",
        ("boundary", true) => "\\B",
        ("backspace", false) => "[\\b]",
        ("backspace", true) => "[^\\b]",
        ("start", false) => "^",
        ("start", true) => return Err("negative start not allowed".to_string()),
        ("end", false) => "$",
        ("end", true) => return Err("negative end not allowed".to_string()),
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(output)
}

fn is_special_symbol(pair: &Pair<Rule>) -> bool {
    pair.clone()
        .into_inner()
        .any(|inner| inner.as_rule() == Rule::symbol_identifier && matches!(inner.as_str(), "start" | "end"))
}

fn compile_negative_class(pair: Pair<Rule>) -> Result<String, String> {
    let content = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::class_content)
        .map(|inner| inner.as_str().to_string())
        .unwrap_or_default();
    Ok(format!("[^{}]", content))
}

fn identifier_of(pair: &Pair<Rule>) -> Option<String> {
    pair.clone()
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::identifier)
        .map(|inner| inner.as_str().to_string())
}

fn compile_variable_invocation(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let name = identifier_of(&pair).unwrap_or_default();
    variables
        .get(&name)
        .cloned()
        .ok_or_else(|| "usage of an uninitialized variable".to_string())
}

fn compile_variable_declaration(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let name = identifier_of(&pair).unwrap_or_default();
    let block = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::block)
        .ok_or_else(|| "missing block".to_string())?;
    let value = compile_block(block, variables)?.concat();
    variables.insert(name, value);
    Ok(String::new())
}

fn compile_group(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let kind = pair.as_str();
    let name = identifier_of(&pair);
    let block = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::block)
        .ok_or_else(|| "missing block".to_string())?;
    let parts = compile_block(block, variables)?;

    Ok(if kind.starts_with("either") {
        format!("(?:{})", parts.join("|"))
    } else if kind.starts_with("capture") {
        match name {
            Some(name) => format!("(?<{}>{})", name, parts.concat()),
            None => format!("({})", parts.concat()),
        }
    } else {
        format!("(?:{})", parts.concat())
    })
}

fn compile_assertion(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let mut negative = false;
    let mut kind = "";
    let mut block = None;

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::not => negative = true,
            Rule::assertion_type => kind = inner.as_str(),
            Rule::block => block = Some(inner),
            _ => {}
        }
    }

    let block = block.ok_or_else(|| "missing block".to_string())?;
    let body = compile_block(block, variables)?.concat();

    Ok(match (kind, negative) {
        ("ahead", false) => format!("(?={})", body),
        ("ahead", true) => format!("(?!{})", body),
        ("behind", false) => format!("(?<={})", body),
        _ => format!("(?<!{})", body),
    })
}

fn needs_group(expression: &str) -> bool {
    let mut characters = expression.chars();
    let first = characters.next();
    let last = expression.chars().last();
    let length = expression.chars().count();

    match length {
        0 => true,
        1 => false,
        2 => first != Some('\\'),
        _ => !matches!((first, last), (Some('('), Some(')')) | (Some('['), Some(']'))),
    }
}

fn compile_quantity(pair: Pair<Rule>) -> Result<String, String> {
    let lazy = pair.as_str().starts_with("lazy");
    let mut quantifier = String::new();

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::quantifier_range => {
                let bounds: Vec<&str> = inner.into_inner().map(|amount| amount.as_str()).collect();
                quantifier = format!("{{{},{}}}", bounds[0], bounds.get(1).copied().unwrap_or(""));
            }
            Rule::amount if quantifier.is_empty() => quantifier = format!("{{{}}}", inner.as_str()),
            Rule::amount => {
                // amount following `over`
                let value: u64 = inner
                    .as_str()
                    .parse::<u64>()
                    .ok()
                    .and_then(|value| value.checked_add(1))
                    .ok_or_else(|| "could not parse an amount".to_string())?;
                quantifier = format!("{{{},}}", value);
            }
            Rule::some => quantifier = "+".to_string(),
            Rule::any => quantifier = "*".to_string(),
            Rule::option => quantifier = "?".to_string(),
            Rule::over => quantifier = "over".to_string(),
            _ => {}
        }
    }

    if lazy {
        quantifier.push('?');
    }
    Ok(quantifier)
}

fn compile_quantifier(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let mut inner = pair.into_inner();
    let quantity = inner.next().ok_or_else(|| "missing quantity".to_string())?;
    let body = inner.next().ok_or_else(|| "missing quantified expression".to_string())?;

    let body_rule = body.as_rule();
    let special_symbol = body_rule == Rule::symbol && is_special_symbol(&body);
    let compiled_body = compile_statement(body, variables)?;

    match body_rule {
        Rule::variable_declaration => return Err("unexpected skipped node in quantifier".to_string()),
        Rule::variable_invocation => return Err("unexpected variable invocation in quantifier".to_string()),
        Rule::assertion_declaration => return Err("unexpected assertion in quantifier".to_string()),
        Rule::symbol if special_symbol => return Err("unexpected special symbol in quantifier".to_string()),
        _ => {}
    }

    let quantifier = compile_quantity(quantity)?;
    let wrapped = if needs_group(&compiled_body) {
        format!("(?:{})", compiled_body)
    } else {
        compiled_body
    };

    Ok(format!("{}{}", wrapped, quantifier))
}
EOF
echo ok"}

