        format!("[^{}-{}]", start, end)
    } else {
        format!("[{}-{}]", start, end)
    })
}

fn compile_symbol(pair: Pair<Rule>) -> Result<String, String> {
    let mut negative = false;
    let mut name = "";

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::not => negative = true,
            Rule::symbol_identifier => name = inner.as_str(),
            _ => {}
        }
    }

    symbol_to_regex(name, negative).map(str::to_string)
}

fn symbol_to_regex(name: &str, negative: bool) -> Result<&'static str, String> {
    let output = match (name, negative) {
        ("char", false) => ".",
        ("char", true) => return Err("negative char not allowed".to_string()),
        ("space", false) => " ",
        ("space", true) => "[^ ]",
        ("whitespace", false) => "\\s",
        ("whitespace", true) => "\\S",
        ("digit", false) => "\\d",
        ("digit", true) => "\\D",
        ("word", false) => "\\w",
        ("word", true) => "\\W",
        ("newline", false) => "\\n",
        ("newline", true) => "[^\\n]",
        ("tab", false) => "\\t",
        ("tab", true) => "[^\\t]",
        ("return", false) => "\\r",
        ("return", true) => "[^\\r]",
        ("feed", false) => "\\f",
        ("feed", true) => "[^\\f]",
        ("null", false) => "\\0",
        ("null", true) => "[^\\0]",
        ("vertical", false) => "\\v",
        ("vertical", true) => "[^\\v]",
        ("alphabetic", false) => "[a-zA-Z]",
        ("alphabetic", true) => "[^a-zA-Z]",
        ("alphanumeric", false) => "[a-zA-Z0-9]",
        ("alphanumeric", true) => "[^a-zA-Z0-9]",
        ("boundary", false) => "\\b",
        ("boundary", true) => "\\B",
        ("backspace", false) => "[\\b]",
        ("backspace", true) => "[^\\b]",
        ("start", false) => "^",
        ("start", true) => return Err("negative start not allowed".to_string()),
        ("end", false) => "$",
        ("end", true) => return Err("negative end not allowed".to_string()),
        _ => return Err("usage of an unrecognized symbol".to_string()),
    };
    Ok(output)
}

fn is_special_symbol(pair: &Pair<Rule>) -> bool {
    pair.clone()
        .into_inner()
        .any(|inner| inner.as_rule() == Rule::symbol_identifier && matches!(inner.as_str(), "start" | "end"))
}

fn compile_negative_class(pair: Pair<Rule>) -> Result<String, String> {
    let content = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::class_content)
        .map(|inner| inner.as_str().to_string())
        .unwrap_or_default();
    Ok(format!("[^{}]", content))
}

fn identifier_of(pair: &Pair<Rule>) -> Option<String> {
    pair.clone()
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::identifier)
        .map(|inner| inner.as_str().to_string())
}

fn compile_variable_invocation(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let name = identifier_of(&pair).unwrap_or_default();
    variables
        .get(&name)
        .cloned()
        .ok_or_else(|| "usage of an uninitialized variable".to_string())
}

fn compile_variable_declaration(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let name = identifier_of(&pair).unwrap_or_default();
    let block = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::block)
        .ok_or_else(|| "missing block".to_string())?;
    let value = compile_block(block, variables)?.concat();
    variables.insert(name, value);
    Ok(String::new())
}

fn compile_group(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let kind = pair.as_str();
    let name = identifier_of(&pair);
    let block = pair
        .into_inner()
        .find(|inner| inner.as_rule() == Rule::block)
        .ok_or_else(|| "missing block".to_string())?;
    let parts = compile_block(block, variables)?;

    Ok(if kind.starts_with("either") {
        format!("(?:{})", parts.join("|"))
    } else if kind.starts_with("capture") {
        match name {
            Some(name) => format!("(?<{}>{})", name, parts.concat()),
            None => format!("({})", parts.concat()),
        }
    } else {
        format!("(?:{})", parts.concat())
    })
}

fn compile_assertion(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let mut negative = false;
    let mut kind = "";
    let mut block = None;

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::not => negative = true,
            Rule::assertion_type => kind = inner.as_str(),
            Rule::block => block = Some(inner),
            _ => {}
        }
    }

    let block = block.ok_or_else(|| "missing block".to_string())?;
    let body = compile_block(block, variables)?.concat();

    Ok(match (kind, negative) {
        ("ahead", false) => format!("(?={})", body),
        ("ahead", true) => format!("(?!{})", body),
        ("behind", false) => format!("(?<={})", body),
        _ => format!("(?<!{})", body),
    })
}

fn needs_group(expression: &str) -> bool {
    let mut characters = expression.chars();
    let first = characters.next();
    let last = expression.chars().last();
    let length = expression.chars().count();

    match length {
        0 => true,
        1 => false,
        2 => first != Some('\\'),
        _ => !matches!((first, last), (Some('('), Some(')')) | (Some('['), Some(']'))),
    }
}

fn compile_quantity(pair: Pair<Rule>) -> Result<String, String> {
    let lazy = pair.as_str().starts_with("lazy");
    let mut quantifier = String::new();

    for inner in pair.into_inner() {
        match inner.as_rule() {
            Rule::quantifier_range => {
                let bounds: Vec<&str> = inner.into_inner().map(|amount| amount.as_str()).collect();
                quantifier = format!("{{{},{}}}", bounds[0], bounds.get(1).copied().unwrap_or(""));
            }
            Rule::amount if quantifier.is_empty() => quantifier = format!("{{{}}}", inner.as_str()),
            Rule::amount => {
                // amount following `over`
                let value: u64 = inner
                    .as_str()
                    .parse::<u64>()
                    .ok()
                    .and_then(|value| value.checked_add(1))
                    .ok_or_else(|| "could not parse an amount".to_string())?;
                quantifier = format!("{{{},}}", value);
            }
            Rule::some => quantifier = "+".to_string(),
            Rule::any => quantifier = "*".to_string(),
            Rule::option => quantifier = "?".to_string(),
            Rule::over => quantifier = "over".to_string(),
            _ => {}
        }
    }

    if lazy {
        quantifier.push('?');
    }
    Ok(quantifier)
}

fn compile_quantifier(pair: Pair<Rule>, variables: &mut Variables) -> Result<String, String> {
    let mut inner = pair.into_inner();
    let quantity = inner.next().ok_or_else(|| "missing quantity".to_string())?;
    let body = inner.next().ok_or_else(|| "missing quantified expression".to_string())?;

    let body_rule = body.as_rule();
    let special_symbol = body_rule == Rule::symbol && is_special_symbol(&body);
    let compiled_body = compile_statement(body, variables)?;

    match body_rule {
        Rule::variable_declaration => return Err("unexpected skipped node in quantifier".to_string()),
        Rule::variable_invocation => return Err("unexpected variable invocation in quantifier".to_string()),
        Rule::assertion_declaration => return Err("unexpected assertion in quantifier".to_string()),
        Rule::symbol if special_symbol => return Err("unexpected special symbol in quantifier".to_string()),
        _ => {}
    }

    let quantifier = compile_quantity(quantity)?;
    let wrapped = if needs_group(&compiled_body) {
        format!("(?:{})", compiled_body)
    } else {
        compiled_body
    };

    Ok(format!("{}{}", wrapped, quantifier))
}
EOF
