/// Writes shell completions for the given shell name to `out`.
/// Returns `false` when the shell is not known.
pub fn write_completions(shell: &str, out: &mut dyn Write) -> bool {
    match shell {
        "bash" => write_bash_completions(out),
        "zsh" => generate(Shell::Zsh, &mut command(), BIN_NAME, out),
        "fish" => generate(Shell::Fish, &mut command(), BIN_NAME, out),
        "elvish" => generate(Shell::Elvish, &mut command(), BIN_NAME, out),
        "powershell" => generate(Shell::PowerShell, &mut command(), BIN_NAME, out),
        _ => return false,
    }
    true
}

/// Bash completions in the classic layout.
fn write_bash_completions(out: &mut dyn Write) {
    let cmd = command();
    let mut shorts = Vec::new();
    let mut longs = Vec::new();
    let mut positionals = Vec::new();
    let mut takes_value = Vec::new();

    for arg in cmd.get_arguments() {
        if let Some(short) = arg.get_short() {
            shorts.push(format!("-{}", short));
        }
        if let Some(long) = arg.get_long() {
            longs.push(format!("--{}", long));
        }
        if arg.is_positional() {
            if let Some(name) = arg.get_value_names().and_then(|names| names.first()) {
                positionals.push(format!("[{}]", name));
            }
        } else if arg.get_action().takes_values() {
            if let Some(long) = arg.get_long() {
                takes_value.push(format!("--{}", long));
            }
            if let Some(short) = arg.get_short() {
                takes_value.push(format!("-{}", short));
            }
        }
    }

    let mut opts: Vec<String> = Vec::new();
    opts.extend(shorts);
    opts.extend(longs);
    opts.extend(positionals);

    let mut script = String::new();
    script.push_str(&format!(
        "_{name}() {{
    local i cur prev opts cmd
    COMPREPLY=()
    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"
    prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"
    cmd=\"\"
    opts=\"\"

    for i in ${{COMP_WORDS[@]}}
    do
        case \"${{cmd}},${{i}}\" in
            \",$1\")
                cmd=\"{name}\"
                ;;
            *)
                ;;
        esac
    done

    case \"${{cmd}}\" in
        {name})
            opts=\"{opts}\"
            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
                return 0
            fi
            case \"${{prev}}\" in
",
        name = BIN_NAME,
        opts = opts.join(" ")
    ));

    for flag in takes_value {
        script.push_str(&format!(
            "                {flag})
                    COMPREPLY=($(compgen -f \"${{cur}}\"))
                    return 0
                    ;;
",
            flag = flag
        ));
    }

    script.push_str(&format!(
        "                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
            return 0
            ;;
    esac
}}

if [[ \"${{BASH_VERSINFO[0]}}\" -eq 4 && \"${{BASH_VERSINFO[1]}}\" -ge 4 || \"${{BASH_VERSINFO[0]}}\" -gt 4 ]]; then
    complete -F _{name} -o nosort -o bashdefault -o default {name}
else
    complete -F _{name} -o bashdefault -o default {name}
fi
",
        name = BIN_NAME
    ));

    let _ = out.write_all(script.as_bytes());
}
