//! Interactive Melody REPL.

use crate::compiler;
use colored::Colorize;
use std::io::{self, BufRead, Write};
use std::process;

const VERSION: &str = "0.20.0";

struct Session {
    lines: Vec<String>,
    undone: Vec<String>,
}

impl Session {
    fn new() -> Self {
        Session {
            lines: Vec::new(),
            undone: Vec::new(),
        }
    }

    fn source(&self) -> String {
        self.lines.join("\n")
    }

    fn print_compiled(&self) {
        match compiler::compile(&self.source()) {
            Ok(regex) => println!("{}\n", regex.bright_blue()),
            Err(error) => println!("{}\n", format!("Error: {}", error).bright_red()),
        }
    }

    fn add_line(&mut self, line: String) {
        self.lines.push(line);
        self.undone.clear();
        match compiler::compile(&self.source()) {
            Ok(regex) => println!("{}\n", regex.bright_blue()),
            Err(error) => {
                self.lines.pop();
                println!("{}\n", format!("Error: {}", error).bright_red());
            }
        }
    }

    fn undo(&mut self) {
        match self.lines.pop() {
            Some(line) => {
                self.undone.push(line);
