//! A small ECMAScript flavoured regular expression engine (parser and
//! backtracking matcher) used to test compiled Melody expressions.
//!
//! The engine follows the ECMAScript "Annex B" (web compatibility) grammar
//! without any flags: matching is case sensitive, `.` does not match line
//! terminators and anchors only match at the ends of the input.

use std::collections::HashSet;
use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    message: &'static str,
}

impl Error {
    fn new(message: &'static str) -> Self {
        Error { message }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.message)
    }
}

impl std::error::Error for Error {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClassEscape {
    Digit,
    NotDigit,
    Word,
    NotWord,
    Space,
    NotSpace,
}

impl ClassEscape {
    fn matches(self, c: char) -> bool {
        match self {
            ClassEscape::Digit => c.is_ascii_digit(),
            ClassEscape::NotDigit => !c.is_ascii_digit(),
            ClassEscape::Word => is_word_char(c),
            ClassEscape::NotWord => !is_word_char(c),
            ClassEscape::Space => is_space_char(c),
            ClassEscape::NotSpace => !is_space_char(c),
        }
    }
}

#[derive(Debug, Clone)]
enum ClassItem {
    Char(char),
    Range(char, char),
    Escape(ClassEscape),
}

#[derive(Debug, Clone)]
enum Node {
    Empty,
    Char(char),
    Any,
    Class { negated: bool, items: Vec<ClassItem> },
    Escape(ClassEscape),
    Start,
    End,
    WordBoundary { negated: bool },
    Group { node: Box<Node>, capture: Option<usize> },
    Alternation(Vec<Node>),
    Sequence(Vec<Node>),
    Repeat { node: Box<Node>, min: u64, max: Option<u64>, greedy: bool },
    Look { node: Box<Node>, behind: bool, negated: bool },
    BackReference(usize),
}

pub fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

pub fn is_space_char(c: char) -> bool {
    matches!(
        c,
        '\t' | '\n' | '\u{000B}' | '\u{000C}' | '\r' | ' ' | '\u{00A0}' | '\u{1680}'
            | '\u{2000}'..='\u{200A}' | '\u{2028}' | '\u{2029}' | '\u{202F}' | '\u{205F}'
            | '\u{3000}' | '\u{FEFF}'
    )
}

fn is_line_terminator(c: char) -> bool {
    matches!(c, '\n' | '\r' | '\u{2028}' | '\u{2029}')
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

struct Parser {
    chars: Vec<char>,
    pos: usize,
    group_count: usize,
    group_names: HashSet<String>,
    /// Total number of capturing groups in the whole pattern, determined by a
    /// pre-scan so that backreferences can be distinguished from octal escapes.
    total_groups: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Quantity {
    Star,
    Plus,
    Question,
    Braced(u64, Option<u64>),
}

impl Parser {
    fn new(pattern: &str) -> Self {
        let chars: Vec<char> = pattern.chars().collect();
        let total_groups = count_capturing_groups(&chars);
        Parser {
            chars,
            pos: 0,
            group_count: 0,
            group_names: HashSet::new(),
            total_groups,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, expected: char) -> bool {
        if self.peek() == Some(expected) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn parse(mut self) -> Result<(Node, usize), Error> {
        let node = self.parse_disjunction()?;
        if self.pos < self.chars.len() {
            // Only a stray closing parenthesis can stop the disjunction.
            return Err(Error::new("unbalanced parenthesis"));
        }
        Ok((node, self.group_count))
    }

    fn parse_disjunction(&mut self) -> Result<Node, Error> {
        let mut alternatives = vec![self.parse_alternative()?];
        while self.eat('|') {
            alternatives.push(self.parse_alternative()?);
        }
        Ok(if alternatives.len() == 1 {
            alternatives.pop().unwrap()
        } else {
            Node::Alternation(alternatives)
        })
    }

    fn parse_alternative(&mut self) -> Result<Node, Error> {
        let mut terms = Vec::new();
        loop {
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => terms.push(self.parse_term()?),
            }
        }
        Ok(match terms.len() {
            0 => Node::Empty,
            1 => terms.pop().unwrap(),
            _ => Node::Sequence(terms),
        })
    }

    /// Tries to parse a braced quantifier (`{n}`, `{n,}`, `{n,m}`) at the
    /// current position. Returns `None` (without consuming anything) when the
    /// braces do not form a quantifier.
    fn try_parse_braced(&mut self) -> Option<(u64, Option<u64>)> {
        let start = self.pos;
        if !self.eat('{') {
            return None;
        }
        let min = match self.parse_number() {
            Some(n) => n,
            None => {
                self.pos = start;
                return None;
            }
        };
        let max = if self.eat(',') {
            if self.peek() == Some('}') {
                None
            } else {
                match self.parse_number() {
                    Some(n) => Some(n),
                    None => {
                        self.pos = start;
                        return None;
                    }
                }
            }
        } else {
            Some(min)
        };
        if !self.eat('}') {
            self.pos = start;
            return None;
        }
        Some((min, max))
    }

    fn parse_number(&mut self) -> Option<u64> {
        let mut value: Option<u64> = None;
        while let Some(c) = self.peek() {
            if let Some(digit) = c.to_digit(10) {
                self.pos += 1;
                value = Some(
                    value
                        .unwrap_or(0)
                        .saturating_mul(10)
                        .saturating_add(digit as u64),
                );
            } else {
                break;
            }
        }
        value
    }

    fn parse_quantity(&mut self) -> Result<Option<Quantity>, Error> {
        match self.peek() {
            Some('*') => {
                self.pos += 1;
                Ok(Some(Quantity::Star))
            }
            Some('+') => {
                self.pos += 1;
                Ok(Some(Quantity::Plus))
            }
            Some('?') => {
                self.pos += 1;
                Ok(Some(Quantity::Question))
            }
            Some('{') => match self.try_parse_braced() {
                Some((min, max)) => {
                    if let Some(max) = max {
                        if min > max {
                            return Err(Error::new("invalid quantifier"));
                        }
                    }
                    Ok(Some(Quantity::Braced(min, max)))
                }
                None => Ok(None),
            },
            _ => Ok(None),
        }
    }

    fn parse_term(&mut self) -> Result<Node, Error> {
        let (atom, quantifiable) = self.parse_atom()?;

        let quantity = match self.parse_quantity()? {
            Some(quantity) => quantity,
            None => return Ok(atom),
        };

        if !quantifiable {
            return Err(Error::new("quantifier not allowed here"));
        }

        let greedy = !self.eat('?');
        let (min, max) = match quantity {
            Quantity::Star => (0, None),
            Quantity::Plus => (1, None),
            Quantity::Question => (0, Some(1)),
            Quantity::Braced(min, max) => (min, max),
        };

        Ok(Node::Repeat {
            node: Box::new(atom),
            min,
            max,
            greedy,
        })
    }

    /// Parses an atom, returning it together with a flag telling whether a
    /// quantifier may follow it.
    fn parse_atom(&mut self) -> Result<(Node, bool), Error> {
        let c = match self.next() {
            Some(c) => c,
            None => return Ok((Node::Empty, true)),
        };

        match c {
            '^' => Ok((Node::Start, false)),
            '$' => Ok((Node::End, false)),
            '.' => Ok((Node::Any, true)),
            '*' | '+' | '?' => Err(Error::new("invalid atom character")),
            '{' => {
                self.pos -= 1;
                if self.try_parse_braced().is_some() {
                    return Err(Error::new("invalid braced quantifier"));
                }
                self.pos += 1;
                Ok((Node::Char('{'), true))
            }
            '(' => self.parse_group(),
            ')' => Err(Error::new("unbalanced parenthesis")),
            '[' => Ok((self.parse_class()?, true)),
            '\\' => self.parse_atom_escape(),
            other => Ok((Node::Char(other), true)),
        }
    }

    fn parse_group(&mut self) -> Result<(Node, bool), Error> {
        if self.eat('?') {
            match self.next() {
                Some(':') => {
                    let node = self.parse_disjunction()?;
                    self.expect_close()?;
                    Ok((
                        Node::Group {
                            node: Box::new(node),
                            capture: None,
                        },
                        true,
                    ))
                }
                Some('=') => self.parse_look(false, false),
                Some('!') => self.parse_look(false, true),
                Some('<') => match self.peek() {
                    Some('=') => {
                        self.pos += 1;
                        self.parse_look(true, false)
                    }
                    Some('!') => {
                        self.pos += 1;
                        self.parse_look(true, true)
                    }
                    _ => {
                        let name = self.parse_group_name()?;
                        if !self.group_names.insert(name) {
                            return Err(Error::new("duplicate capture group name"));
                        }
                        self.group_count += 1;
                        let index = self.group_count;
                        let node = self.parse_disjunction()?;
                        self.expect_close()?;
                        Ok((
                            Node::Group {
                                node: Box::new(node),
                                capture: Some(index),
                            },
                            true,
                        ))
                    }
                },
                _ => Err(Error::new("invalid token at named capture group identifier")),
            }
        } else {
            self.group_count += 1;
            let index = self.group_count;
            let node = self.parse_disjunction()?;
            self.expect_close()?;
            Ok((
                Node::Group {
                    node: Box::new(node),
                    capture: Some(index),
                },
                true,
            ))
        }
    }

    fn parse_look(&mut self, behind: bool, negated: bool) -> Result<(Node, bool), Error> {
        let node = self.parse_disjunction()?;
        self.expect_close()?;
        Ok((
            Node::Look {
                node: Box::new(node),
                behind,
                negated,
            },
            !behind,
        ))
    }

    fn expect_close(&mut self) -> Result<(), Error> {
        if self.eat(')') {
            Ok(())
        } else {
            Err(Error::new("unbalanced parenthesis"))
        }
    }

    fn parse_group_name(&mut self) -> Result<String, Error> {
        let mut name = String::new();
        match self.next() {
            Some(c) if is_identifier_start(c) => name.push(c),
            _ => return Err(Error::new("invalid token at named capture group identifier")),
        }
        loop {
            match self.next() {
                Some('>') => return Ok(name),
                Some(c) if is_identifier_part(c) => name.push(c),
                _ => return Err(Error::new("invalid token at named capture group identifier")),
            }
        }
    }

    fn parse_atom_escape(&mut self) -> Result<(Node, bool), Error> {
        let c = match self.next() {
            Some(c) => c,
            None => return Ok((Node::Char('\\'), true)),
        };

        match c {
            'b' => Ok((Node::WordBoundary { negated: false }, true)),
            'B' => Ok((Node::WordBoundary { negated: true }, true)),
            'd' => Ok((Node::Escape(ClassEscape::Digit), true)),
            'D' => Ok((Node::Escape(ClassEscape::NotDigit), true)),
            'w' => Ok((Node::Escape(ClassEscape::Word), true)),
            'W' => Ok((Node::Escape(ClassEscape::NotWord), true)),
            's' => Ok((Node::Escape(ClassEscape::Space), true)),
            'S' => Ok((Node::Escape(ClassEscape::NotSpace), true)),
            '1'..='9' => {
                // A decimal escape is a backreference when a matching group
                // exists, otherwise it falls back to a legacy octal escape or
                // identity escape.
                let start = self.pos - 1;
                let value = self.parse_number().unwrap_or(0);
                if value as usize <= self.total_groups {
                    return Ok((Node::BackReference(value as usize), true));
                }
                self.pos = start;
                if c >= '8' {
                    self.pos += 1;
                    return Ok((Node::Char(c), true));
                }
                Ok((Node::Char(self.parse_legacy_octal()), true))
            }
            '0' => {
                self.pos -= 1;
                Ok((Node::Char(self.parse_legacy_octal()), true))
            }
            'k' => {
                // Without named groups `\k` is an identity escape.
                if self.group_names.is_empty() && !pattern_has_named_groups(&self.chars) {
                    return Ok((Node::Char('k'), true));
                }
                if !self.eat('<') {
                    return Err(Error::new("invalid token at named capture group identifier"));
                }
                let name = self.parse_group_name()?;
                Ok((Node::BackReference(self.named_group_index(&name)), true))
            }
            _ => {
                self.pos -= 1;
                let c = self.parse_character_escape(false);
                Ok((Node::Char(c), true))
            }
        }
    }

    fn named_group_index(&self, name: &str) -> usize {
        // Named back references are resolved by scanning for the group's
        // position in the pattern.
        let mut index = 0;
        let mut i = 0;
        while i < self.chars.len() {
            if self.chars[i] == '\\' {
                i += 2;
                continue;
            }
            if self.chars[i] == '(' {
                if self.chars.get(i + 1) != Some(&'?') {
                    index += 1;
                } else if self.chars.get(i + 2) == Some(&'<')
                    && !matches!(self.chars.get(i + 3), Some('=') | Some('!'))
                {
                    index += 1;
                    let rest: String = self.chars[i + 3..].iter().collect();
                    if rest.starts_with(&format!("{}>", name)) {
                        return index;
                    }
                }
            }
            i += 1;
        }
        0
    }

    /// Parses a legacy octal escape (`\0` .. `\377`); the backslash has
    /// already been consumed and the current position points at the first
    /// digit.
    fn parse_legacy_octal(&mut self) -> char {
        let mut value: u32 = 0;
        let mut digits = 0;
        while digits < 3 {
            match self.peek() {
                Some(c) if ('0'..='7').contains(&c) => {
                    let next = value * 8 + c.to_digit(8).unwrap();
                    if next > 0o377 {
                        break;
                    }
                    value = next;
                    self.pos += 1;
                    digits += 1;
                }
                _ => break,
            }
        }
        char::from_u32(value).unwrap_or('\0')
    }

    /// Parses the escape following a backslash that is a plain character
    /// escape (control escapes, hex/unicode escapes and identity escapes).
    fn parse_character_escape(&mut self, in_class: bool) -> char {
        let c = match self.next() {
            Some(c) => c,
            None => return '\\',
        };
        match c {
            't' => '\t',
            'n' => '\n',
            'v' => '\u{000B}',
            'f' => '\u{000C}',
            'r' => '\r',
            'c' => match self.peek() {
                Some(letter) if letter.is_ascii_alphabetic() => {
                    self.pos += 1;
                    char::from_u32(letter as u32 % 32).unwrap_or('\0')
                }
                Some(other) if in_class && (other.is_ascii_digit() || other == '_') => {
                    self.pos += 1;
                    char::from_u32(other as u32 % 32).unwrap_or('\0')
                }
                _ => {
                    // `\c` not followed by a control letter is a literal
                    // backslash; the `c` is re-read as a normal character.
                    self.pos -= 1;
                    '\\'
                }
            },
            'x' => {
                let first = self.next();
                let second = self.next();
                match (
                    first.and_then(|c| c.to_digit(16)),
                    second.and_then(|c| c.to_digit(16)),
                ) {
                    (Some(high), Some(low)) => char::from_u32(high * 16 + low).unwrap_or('x'),
                    _ => 'x',
                }
            }
            'u' => {
                let digits: Vec<Option<u32>> = (0..4).map(|i| self.peek_at(i).and_then(|c| c.to_digit(16))).collect();
                if digits.iter().all(Option::is_some) {
                    self.pos += 4;
                    let value = digits.iter().fold(0u32, |acc, d| acc * 16 + d.unwrap());
                    char::from_u32(value).unwrap_or('\u{FFFD}')
                } else {
                    'u'
                }
            }
            other => other,
        }
    }

    fn parse_class(&mut self) -> Result<Node, Error> {
        let negated = self.eat('^');
        let mut items = Vec::new();

        loop {
            let c = match self.peek() {
                None => return Err(Error::new("unbalanced bracket")),
                Some(c) => c,
            };
            if c == ']' {
                self.pos += 1;
                break;
            }

            let first = self.parse_class_atom()?;

            if self.peek() == Some('-') && self.peek_at(1).is_some() && self.peek_at(1) != Some(']') {
                self.pos += 1;
                let second = self.parse_class_atom()?;
                match (first, second) {
                    (ClassItem::Char(start), ClassItem::Char(end)) => {
                        if start > end {
                            return Err(Error::new(
                                "range values reversed, start char code is greater than end char code.",
                            ));
                        }
                        items.push(ClassItem::Range(start, end));
                    }
                    _ => {
                        return Err(Error::new(
                            "range values reversed, start char code is greater than end char code.",
                        ))
                    }
                }
            } else {
                items.push(first);
            }
        }

        Ok(Node::Class { negated, items })
    }

    fn parse_class_atom(&mut self) -> Result<ClassItem, Error> {
        let c = match self.next() {
            Some(c) => c,
            None => return Err(Error::new("unbalanced bracket")),
        };
        if c != '\\' {
            return Ok(ClassItem::Char(c));
        }

        let escaped = match self.peek() {
            Some(c) => c,
            None => return Err(Error::new("unbalanced bracket")),
        };

        match escaped {
            'd' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::Digit))
            }
            'D' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::NotDigit))
            }
            'w' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::Word))
            }
            'W' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::NotWord))
            }
            's' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::Space))
            }
            'S' => {
                self.pos += 1;
                Ok(ClassItem::Escape(ClassEscape::NotSpace))
            }
            'b' => {
                self.pos += 1;
                Ok(ClassItem::Char('\u{0008}'))
            }
            '0'..='7' => Ok(ClassItem::Char(self.parse_legacy_octal())),
            _ => Ok(ClassItem::Char(self.parse_character_escape(true))),
        }
    }
}

fn is_identifier_start(c: char) -> bool {
    c == '$' || c == '_' || c.is_alphabetic()
}

fn is_identifier_part(c: char) -> bool {
    c == '$' || c == '_' || c.is_alphanumeric() || c == '\u{200C}' || c == '\u{200D}'
}

fn count_capturing_groups(chars: &[char]) -> usize {
    let mut count = 0;
    let mut in_class = false;
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '\\' => i += 1,
            '[' => in_class = true,
            ']' => in_class = false,
            '(' if !in_class => {
                if chars.get(i + 1) != Some(&'?') {
                    count += 1;
                } else if chars.get(i + 2) == Some(&'<')
                    && !matches!(chars.get(i + 3), Some('=') | Some('!'))
                {
                    count += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    count
}

fn pattern_has_named_groups(chars: &[char]) -> bool {
    let mut i = 0;
    while i + 2 < chars.len() {
        if chars[i] == '\\' {
            i += 2;
            continue;
        }
        if chars[i] == '(' && chars[i + 1] == '?' && chars[i + 2] == '<' {
            if !matches!(chars.get(i + 3), Some('=') | Some('!')) {
                return true;
            }
        }
        i += 1;
    }
    false
}

// ---------------------------------------------------------------------------
// Matcher
// ---------------------------------------------------------------------------

type Captures = Vec<Option<(usize, usize)>>;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Direction {
    Forward,
    Backward,
}

struct Matcher<'a> {
    input: &'a [char],
}

impl<'a> Matcher<'a> {
    fn char_matches(node: &Node, c: char) -> bool {
        match node {
            Node::Char(expected) => *expected == c,
            Node::Any => !is_line_terminator(c),
            Node::Escape(escape) => escape.matches(c),
            Node::Class { negated, items } => {
                let found = items.iter().any(|item| match item {
                    ClassItem::Char(expected) => *expected == c,
                    ClassItem::Range(start, end) => *start <= c && c <= *end,
                    ClassItem::Escape(escape) => escape.matches(c),
                });
                found != *negated
            }
            _ => false,
        }
    }

    fn is_word_at(&self, index: isize) -> bool {
        if index < 0 {
            return false;
        }
        self.input
            .get(index as usize)
            .map(|&c| is_word_char(c))
            .unwrap_or(false)
    }

    /// Matches `node` at `pos`, calling `k` with the new position for every
    /// possible way the node can match (in priority order) until `k` returns
    /// `true`.
    fn run(
        &self,
        node: &Node,
        pos: usize,
        dir: Direction,
        caps: &mut Captures,
        k: &mut dyn FnMut(usize, &mut Captures) -> bool,
    ) -> bool {
        match node {
            Node::Empty => k(pos, caps),
            Node::Char(_) | Node::Any | Node::Escape(_) | Node::Class { .. } => match dir {
                Direction::Forward => match self.input.get(pos) {
                    Some(&c) if Self::char_matches(node, c) => k(pos + 1, caps),
                    _ => false,
                },
                Direction::Backward => {
                    if pos == 0 {
                        return false;
                    }
                    if Self::char_matches(node, self.input[pos - 1]) {
                        k(pos - 1, caps)
                    } else {
                        false
                    }
                }
            },
            Node::Start => pos == 0 && k(pos, caps),
            Node::End => pos == self.input.len() && k(pos, caps),
            Node::WordBoundary { negated } => {
                let before = self.is_word_at(pos as isize - 1);
                let after = self.is_word_at(pos as isize);
                ((before != after) != *negated) && k(pos, caps)
            }
            Node::Group { node, capture } => match capture {
                None => self.run(node, pos, dir, caps, k),
                Some(index) => {
                    let index = *index;
                    let saved = caps[index];
                    let matched = self.run(node, pos, dir, caps, &mut |end, caps| {
                        let previous = caps[index];
                        caps[index] = Some(match dir {
                            Direction::Forward => (pos, end),
                            Direction::Backward => (end, pos),
                        });
                        if k(end, caps) {
                            true
                        } else {
                            caps[index] = previous;
                            false
                        }
                    });
                    if !matched {
                        caps[index] = saved;
                    }
                    matched
                }
            },
            Node::Alternation(alternatives) => {
                for alternative in alternatives {
                    if self.run(alternative, pos, dir, caps, k) {
                        return true;
                    }
                }
                false
            }
            Node::Sequence(terms) => self.run_sequence(terms, pos, dir, caps, k),
            Node::Repeat {
                node,
                min,
                max,
                greedy,
            } => self.run_repeat(node, *min, *max, *greedy, 0, pos, None, dir, caps, k),
            Node::Look {
                node,
                behind,
                negated,
            } => {
                let look_dir = if *behind {
                    Direction::Backward
                } else {
                    Direction::Forward
                };
                let mut snapshot = caps.clone();
                let matched = self.run(node, pos, look_dir, &mut snapshot, &mut |_, _| true);
                if *negated {
                    if matched {
                        false
                    } else {
                        k(pos, caps)
                    }
                } else if matched {
                    let saved = caps.clone();
                    *caps = snapshot;
                    if k(pos, caps) {
                        true
                    } else {
                        *caps = saved;
                        false
                    }
                } else {
                    false
                }
            }
            Node::BackReference(index) => {
                let captured = caps.get(*index).copied().flatten();
                let (start, end) = match captured {
                    Some(span) => span,
                    None => return k(pos, caps),
                };
                let text = &self.input[start..end];
                match dir {
                    Direction::Forward => {
                        if pos + text.len() <= self.input.len()
                            && self.input[pos..pos + text.len()] == *text
                        {
                            k(pos + text.len(), caps)
                        } else {
                            false
                        }
                    }
                    Direction::Backward => {
                        if pos >= text.len() && self.input[pos - text.len()..pos] == *text {
                            k(pos - text.len(), caps)
                        } else {
                            false
                        }
                    }
                }
            }
        }
    }

    fn run_sequence(
        &self,
        terms: &[Node],
        pos: usize,
        dir: Direction,
        caps: &mut Captures,
        k: &mut dyn FnMut(usize, &mut Captures) -> bool,
    ) -> bool {
        if terms.is_empty() {
            return k(pos, caps);
        }
        match dir {
            Direction::Forward => {
                let (first, rest) = terms.split_first().unwrap();
                self.run(first, pos, dir, caps, &mut |next, caps| {
                    self.run_sequence(rest, next, dir, caps, k)
                })
            }
            Direction::Backward => {
                let (last, rest) = terms.split_last().unwrap();
                self.run(last, pos, dir, caps, &mut |next, caps| {
                    self.run_sequence(rest, next, dir, caps, k)
                })
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn run_repeat(
        &self,
        node: &Node,
        min: u64,
        max: Option<u64>,
        greedy: bool,
        count: u64,
        pos: usize,
        last_pos: Option<usize>,
        dir: Direction,
        caps: &mut Captures,
        k: &mut dyn FnMut(usize, &mut Captures) -> bool,
    ) -> bool {
        // An iteration beyond the minimum that consumes nothing cannot lead
        // to further progress.
        if count > min && last_pos == Some(pos) {
            return false;
        }

        if max == Some(count) {
            return k(pos, caps);
        }

        let mut try_iteration = |caps: &mut Captures| {
            self.clear_captures(node, caps);
            self.run(node, pos, dir, caps, &mut |next, caps| {
                self.run_repeat(node, min, max, greedy, count + 1, next, Some(pos), dir, caps, k)
            })
        };

        if count < min {
            return try_iteration(caps);
        }

        if greedy {
            let saved = caps.clone();
            if try_iteration(caps) {
                return true;
            }
            *caps = saved;
            k(pos, caps)
        } else {
            let saved = caps.clone();
            if k(pos, caps) {
                return true;
            }
            *caps = saved;
            try_iteration(caps)
        }
    }

    fn clear_captures(&self, node: &Node, caps: &mut Captures) {
        match node {
            Node::Group { node, capture } => {
                if let Some(index) = capture {
                    caps[*index] = None;
                }
                self.clear_captures(node, caps);
            }
            Node::Alternation(nodes) | Node::Sequence(nodes) => {
                for inner in nodes {
                    self.clear_captures(inner, caps);
                }
            }
            Node::Repeat { node, .. } | Node::Look { node, .. } => self.clear_captures(node, caps),
            _ => {}
        }
    }
}

/// A compiled regular expression.
pub struct Regex {
    node: Node,
    group_count: usize,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, Error> {
        let (node, group_count) = Parser::new(pattern).parse()?;
        Ok(Regex { node, group_count })
    }

    /// Returns whether the expression matches anywhere in `input`.
    pub fn is_match(&self, input: &str) -> bool {
        let chars: Vec<char> = input.chars().collect();
        let matcher = Matcher { input: &chars };
        for start in 0..=chars.len() {
            let mut caps: Captures = vec![None; self.group_count + 1];
            if matcher.run(&self.node, start, Direction::Forward, &mut caps, &mut |_, _| true) {
                return true;
            }
        }
        false
    }
}
