            }
            *caps = saved;
            k(pos, caps)
        } else {
            let saved = caps.clone();
            if k(pos, caps) {
                return true;
            }
            *caps = saved;
            self.repeat_iteration(node, min, max, greedy, count, pos, dir, caps, k)
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn repeat_iteration(
        &self,
        node: &Node,
        min: u64,
        max: Option<u64>,
        greedy: bool,
        count: u64,
        pos: usize,
        dir: Direction,
        caps: &mut Captures,
        k: &mut dyn FnMut(usize, &mut Captures) -> bool,
    ) -> bool {
        self.clear_captures(node, caps);
        self.run(node, pos, dir, caps, &mut |next, caps| {
            self.run_repeat(node, min, max, greedy, count + 1, next, Some(pos), dir, caps, k)
        })
