#!/usr/bin/env python3
import subprocess, sys, random, os

ORIG = '/workspace/executable'
MINE = '/tmp/mine'

def run(binary, src, args=None):
    args = args or []
    r = subprocess.run([binary] + args, input=src.encode('utf-8', 'surrogateescape'), capture_output=True, timeout=10)
    return r.returncode, r.stdout, r.stderr

def compare(src, args=None, verbose=True):
    a = run(ORIG, src, args)
    b = run(MINE, src, args)
    if a != b:
        if verbose:
            print("=== DIFF for input %r args=%r" % (src, args))
            print("--- orig rc=%d\n%s%s" % (a[0], a[1].decode('utf-8','replace'), a[2].decode('utf-8','replace')))
            print("--- mine rc=%d\n%s%s" % (b[0], b[1].decode('utf-8','replace'), b[2].decode('utf-8','replace')))
        return False
    return True

if __name__ == '__main__':
    corpus_file = sys.argv[1]
    inputs = open(corpus_file).read().split('\n=====\n')
    ok = 0; bad = 0
    for src in inputs:
        if compare(src):
            ok += 1
        else:
            bad += 1
    print("ok=%d bad=%d" % (ok, bad))
